<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3'; import PageHeader from '@/Components/Shared/PageHeader.vue'; import FormActions from '@/Components/Forms/FormActions.vue'; import PublicPageForm from '@/components/admin/PublicPageForm.vue'; import type {PublicPageRecord} from '@/types/publicPages';
const props=defineProps<{publicPage:PublicPageRecord; types:Record<string,string>; navigationLocations:Record<string,string>; statuses:string[]}>();
const form=useForm({title:props.publicPage.title,slug:props.publicPage.slug,eyebrow:props.publicPage.eyebrow??'',introduction:props.publicPage.introduction??'',content:props.publicPage.content??'',page_type:props.publicPage.page_type,status:props.publicPage.status,published_at:props.publicPage.published_at?.slice(0,16)??'',is_active:props.publicPage.is_active,navigation_label:props.publicPage.navigation_label??'',navigation_locations:props.publicPage.navigation_locations??[],sort_order:props.publicPage.sort_order,seo_title:props.publicPage.seo_title??'',seo_description:props.publicPage.seo_description??'',canonical_url:props.publicPage.canonical_url??''});
function submit(){form.put(`/admin/public-pages/${props.publicPage.slug}`,{preserveScroll:true});}
</script>
<template><Head :title="`Edit ${publicPage.title}`"/><AppLayout><div class="space-y-8 p-6"><PageHeader :title="`Edit ${publicPage.title}`" description="Update this public informational page."/><form class="space-y-8" @submit.prevent="submit"><PublicPageForm :form="form" :types="types" :navigation-locations="navigationLocations" :statuses="statuses"/><FormActions submit-label="Save Changes" :processing="form.processing" @cancel="router.visit('/admin/public-pages')"/></form></div></AppLayout></template>
